const listPreviewTunnelEvents = `-- name: ListPreviewTunnelEvents :many
SELECT id, actor_user_id, actor_type, event_type, resource_type, resource_id, idempotency_key, metadata, created_at, account_id, actor_id, change_type, outcome, request_id, correlation_id, source_device_id, cursor_sequence
FROM audit_events
WHERE account_id = $1
  AND resource_type = $2
  AND resource_id = $3
  AND cursor_sequence > $4
ORDER BY cursor_sequence ASC
LIMIT $5
`

type ListPreviewTunnelEventsParams struct {
	AccountID     sql.NullString
	ResourceType  string
	ResourceID    string
	AfterSequence sql.NullInt64
	RowLimit      int32
}

func (q *Queries) ListPreviewTunnelEvents(ctx context.Context, arg ListPreviewTunnelEventsParams) ([]AuditEvent, error) {
	rows, err := q.db.Query(ctx, listPreviewTunnelEvents,
		arg.AccountID,
		arg.ResourceType,
		arg.ResourceID,
		arg.AfterSequence,
		arg.RowLimit,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []AuditEvent
	for rows.Next() {
		var i AuditEvent
		if err := rows.Scan(
			&i.ID,
			&i.ActorUserID,
			&i.ActorType,
			&i.EventType,
			&i.ResourceType,
			&i.ResourceID,
			&i.IdempotencyKey,
			&i.Metadata,
			&i.CreatedAt,
			&i.AccountID,
			&i.ActorID,
			&i.ChangeType,
			&i.Outcome,
			&i.RequestID,
			&i.CorrelationID,
			&i.SourceDeviceID,
			&i.CursorSequence,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

